UPDATE TBL_BANK_LOAN
LOAN_NO = #{loanNo}, BANK_NAME = #{bankName}, BANK_ACCOUNT = #{bankAccount}, CONTRACT_NO = #{contractNo}, LOAN_TYPE = #{loanType}, LOAN_AMOUNT = #{loanAmount}, LOAN_RATE = #{loanRate}, LOAN_START_DATE = #{loanStartDate}, LOAN_END_DATE = #{loanEndDate}, LOAN_TERM = #{loanTerm}, REPAYMENT_METHOD = #{repaymentMethod}, PAYMENT_ACCOUNT = #{paymentAccount}, GUARANTEE_TYPE = #{guaranteeType}, GUARANTEE_AMOUNT = #{guaranteeAmount}, CURRENCY = #{currency}, LOAN_STATUS = #{loanStatus}, REMAINING_PRINCIPAL = #{remainingPrincipal}, TOTAL_REPAID = #{totalRepaid}, TOTAL_INTEREST = #{totalInterest}, OPERATOR = #{operator}, REMARK = #{remark}, UPDATE_TIME = #{updateTime}, UPDATE_BY = #{updateBy},
WHERE LOAN_ID = #{loanId}

UPDATE TBL_BANK_LOAN
SET DELETE_FLAG = 1, UPDATE_TIME = CURRENT_TIMESTAMP
WHERE LOAN_ID = #{loanId}
